    <style>
      :root {
        color-scheme: light;
        --bg: #f3f7fb;
        --surface: #ffffff;
        --surface-strong: #0f172a;
        --text: #0f172a;
        --muted: #475569;
        --border: #cbd5e1;
        --border-strong: #94a3b8;
        --primary: #2563eb;
        --primary-dark: #1d4ed8;
        --error: #b91c1c;
        --error-bg: #fef2f2;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(37, 99, 235, 0.14), transparent 30%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        padding: 0.75rem 1rem;
        background: var(--surface-strong);
        color: #ffffff;
        border-radius: 0.75rem;
        transform: translateY(-200%);
        transition: transform 0.2s ease;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #93c5fd;
        outline-offset: 2px;
      }

      main {
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 3rem 1.5rem;
      }

      .page-shell {
        width: min(100%, 1080px);
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(320px, 460px);
        gap: 2rem;
        align-items: stretch;
      }

      .hero,
      .panel {
        background: rgba(255, 255, 255, 0.82);
        backdrop-filter: blur(16px);
        border: 1px solid rgba(148, 163, 184, 0.18);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
      }

      .hero {
        padding: 3rem;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-width: 0;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--primary-dark);
      }

      .hero h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2.25rem, 4vw, 3.5rem);
        line-height: 1.05;
      }

      .hero p {
        margin: 0;
        max-width: 34rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .feature-list {
        display: grid;
        gap: 1rem;
        margin: 2rem 0 0;
        padding: 0;
        list-style: none;
      }

      .feature-list li {
        display: flex;
        gap: 0.875rem;
        align-items: flex-start;
        color: var(--muted);
      }

      .feature-dot {
        flex: 0 0 auto;
        width: 1rem;
        height: 1rem;
        margin-top: 0.35rem;
        border-radius: 999px;
        background: linear-gradient(135deg, #60a5fa, #2563eb);
      }

      .panel {
        padding: 2rem;
      }

      .panel h2 {
        margin: 0 0 0.5rem;
        font-size: 1.5rem;
      }

      .panel-copy {
        margin: 0 0 1.5rem;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-weight: 700;
      }

      .required-indicator {
        color: var(--error);
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        padding: 0.95rem 1rem;
        font: inherit;
        color: inherit;
        background: var(--surface);
        transition:
          border-color 0.2s ease,
          box-shadow 0.2s ease,
          transform 0.2s ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:hover {
        border-color: var(--border-strong);
      }

      input:focus-visible {
        border-color: var(--primary);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.18);
      }

      input[aria-invalid="true"] {
        border-color: var(--error);
        background: var(--error-bg);
      }

      .field-help {
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .field-error {
        min-height: 1.25rem;
        color: var(--error);
        font-size: 0.95rem;
        line-height: 1.4;
      }

      .field-error:empty {
        display: none;
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        font-size: 0.95rem;
        color: #166534;
      }

      .status-message.error {
        color: var(--error);
      }

      .actions {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        flex-wrap: wrap;
        margin-top: 0.25rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.5rem;
        font: inherit;
        font-weight: 700;
        color: #ffffff;
        background: linear-gradient(135deg, var(--primary), var(--primary-dark));
        cursor: pointer;
        transition:
          transform 0.2s ease,
          box-shadow 0.2s ease,
          filter 0.2s ease;
        box-shadow: 0 18px 30px rgba(37, 99, 235, 0.24);
      }

      button:hover {
        transform: translateY(-1px);
        filter: brightness(1.04);
      }

      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow:
          0 0 0 4px rgba(37, 99, 235, 0.2),
          0 18px 30px rgba(37, 99, 235, 0.24);
      }

      @media (max-width: 840px) {
        .page-shell {
          grid-template-columns: 1fr;
        }

        .hero,
        .panel {
          padding: 1.5rem;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        .hero,
        .panel,
        input,
        button {
          background: Canvas;
          color: CanvasText;
          border: 1px solid ButtonBorder;
          box-shadow: none;
        }

        .skip-link {
          background: ButtonFace;
          color: ButtonText;
        }

        .feature-dot {
          background: currentColor;
        }

        input:focus-visible,
        button:focus-visible,
        .skip-link:focus {
          outline: 2px solid Highlight;
          outline-offset: 2px;
          box-shadow: none;
        }

        .field-error,
        .required-indicator,
        .status-message.error {
          color: Mark;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const fields = [
        {
          id: "fullName",
          name: "fullName",
          label: "Full name",
          type: "text",
          placeholder: "Jordan Lee",
          required: true,
          helperText: "",
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          placeholder: "jordan@example.com",
          required: true,
          helperText: "",
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          required: false,
          helperText:
            "Optional. Use digits, spaces, dashes, or parentheses, for example (555) 123-4567.",
        },
      ];

      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {
          fullName: "",
          email: "",
          phone: "",
        },
        status: "",
        statusType: "success",
      };

      function App() {
        return `
          <main id="main-content">
            <div class="page-shell">
              ${SupportHero()}
              ${ContactPanel()}
            </div>
          </main>
        `;
      }

      function SupportHero() {
        return `
          <section class="hero" aria-labelledby="support-title">
            <div>
              <span class="eyebrow">Support team</span>
              <h1 id="support-title">Get help from a product specialist.</h1>
              <p>
                Send us your details and a short note. We will follow up with the
                right support path for your account, billing, or technical issue.
              </p>
            </div>
            <ul class="feature-list" aria-label="Support highlights">
              <li><span class="feature-dot" aria-hidden="true"></span><span>Fast routing to the right team based on your request.</span></li>
              <li><span class="feature-dot" aria-hidden="true"></span><span>Clear next steps with email follow-up for required details.</span></li>
              <li><span class="feature-dot" aria-hidden="true"></span><span>Modern, accessible form design that works across screen sizes.</span></li>
            </ul>
          </section>
        `;
      }

      function ContactPanel() {
        return `
          <section class="panel" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title">Contact support</h2>
            <p class="panel-copy">
              Fields marked with <span class="required-indicator">*</span> are required.
            </p>
            <form id="contact-form" novalidate>
              ${fields.map(FormField).join("")}
              <div class="actions">
                <button type="submit">Submit request</button>
                <p
                  id="form-status"
                  class="status-message${state.statusType === "error" ? " error" : ""}"
                  aria-live="polite"
                >${escapeHtml(state.status)}</p>
              </div>
            </form>
          </section>
        `;
      }

      function FormField(field) {
        const errorId = `${field.id}-error`;
        const helpId = field.helperText ? `${field.id}-help` : "";
        const describedBy = [helpId, errorId].filter(Boolean).join(" ");
        const errorMessage = state.errors[field.name];
        const value = state.values[field.name];

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.name}"
              type="${field.type}"
              value="${escapeHtml(value)}"
              placeholder="${field.placeholder}"
              ${field.required ? "required aria-required=\"true\"" : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${errorMessage ? 'aria-invalid="true"' : ""}
              autocomplete="${field.name === "fullName" ? "name" : field.name === "email" ? "email" : "tel"}"
            />
            ${
              field.helperText
                ? `<p class="field-help" id="${helpId}">${field.helperText}</p>`
                : ""
            }
            <p class="field-error" id="${errorId}" aria-live="polite">${escapeHtml(errorMessage)}</p>
          </div>
        `;
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName") {
          if (!trimmedValue) {
            return "Enter your full name.";
          }

          if (trimmedValue.length < 2 || !trimmedValue.includes(" ")) {
            return "Enter your first and last name.";
          }
        }

        if (name === "email") {
          if (!trimmedValue) {
            return "Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
        }

        if (name === "phone") {
          if (!trimmedValue) {
            return "";
          }

          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Use digits, spaces, dashes, or parentheses for the phone number.";
          }
        }

        return "";
      }

      function validateAll() {
        const nextErrors = {};

        for (const field of fields) {
          nextErrors[field.name] = validateField(field.name, state.values[field.name]);
        }

        state.errors = nextErrors;
        return !Object.values(nextErrors).some(Boolean);
      }

      function updateField(name, value) {
        state.values[name] = value;
        state.errors[name] = validateField(name, value);
        state.status = "";
        state.statusType = "success";
        render();
      }

      function focusFirstInvalidField() {
        const firstInvalidField = fields.find((field) => state.errors[field.name]);
        if (!firstInvalidField) {
          return;
        }

        const element = document.getElementById(firstInvalidField.id);
        if (element) {
          element.focus();
        }
      }

      function onSubmit(event) {
        event.preventDefault();

        if (!validateAll()) {
          state.status = "Please correct the highlighted fields and try again.";
          state.statusType = "error";
          render();
          focusFirstInvalidField();
          return;
        }

        state.status = "Your support request is ready to send.";
        state.statusType = "success";
        render();
      }

      function attachEvents() {
        const form = document.getElementById("contact-form");
        form.addEventListener("submit", onSubmit);

        fields.forEach((field) => {
          const input = document.getElementById(field.id);
          input.addEventListener("input", (event) => {
            updateField(field.name, event.target.value);
          });
          input.addEventListener("blur", (event) => {
            state.errors[field.name] = validateField(field.name, event.target.value);
            render();
          });
        });
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        attachEvents();
      }

      render();
    </script>
  </body>
</html>
