          border: 1px solid ButtonBorder;
          box-shadow: none;
        }

        .skip-link {
          background: ButtonFace;
          color: ButtonText;
        }

        .feature-dot {
          background: currentColor;
        }

        input:focus-visible,
        button:focus-visible,
        .skip-link:focus {
          outline: 2px solid Highlight;
          outline-offset: 2px;
          box-shadow: none;
        }

        .field-error,
        .required-indicator,
        .status-message.error {
          color: Mark;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const fields = [
        {
          id: "fullName",
          name: "fullName",
          label: "Full name",
          type: "text",
          placeholder: "Jordan Lee",
          required: true,
          helperText: "",
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          placeholder: "jordan@example.com",
          required: true,
          helperText: "",
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          required: false,
          helperText:
            "Optional. Use digits, spaces, dashes, or parentheses, for example (555) 123-4567.",
        },
      ];

      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {
          fullName: "",
          email: "",
          phone: "",
        },
        status: "",
        statusType: "success",
      };

      function App() {
        return `
          <main id="main-content">
            <div class="page-shell">
              ${SupportHero()}
              ${ContactPanel()}
            </div>
          </main>
        `;
      }

      function SupportHero() {
        return `
          <section class="hero" aria-labelledby="support-title">
            <div>
              <span class="eyebrow">Support team</span>
              <h1 id="support-title">Get help from a product specialist.</h1>
              <p>
                Send us your details and a short note. We will follow up with the
                right support path for your account, billing, or technical issue.
              </p>
            </div>
            <ul class="feature-list" aria-label="Support highlights">
              <li><span class="feature-dot" aria-hidden="true"></span><span>Fast routing to the right team based on your request.</span></li>
              <li><span class="feature-dot" aria-hidden="true"></span><span>Clear next steps with email follow-up for required details.</span></li>
              <li><span class="feature-dot" aria-hidden="true"></span><span>Modern, accessible form design that works across screen sizes.</span></li>
            </ul>
          </section>
        `;
      }

      function ContactPanel() {
        return `
          <section class="panel" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title">Contact support</h2>
            <p class="panel-copy">
              Fields marked with <span class="required-indicator">*</span> are required.
            </p>
            <form id="contact-form" novalidate>
              ${fields.map(FormField).join("")}
              <div class="actions">
                <button type="submit">Submit request</button>
                <p
                  id="form-status"
                  class="status-message${state.statusType === "error" ? " error" : ""}"
                  aria-live="polite"
                >${escapeHtml(state.status)}</p>
              </div>
            </form>
          </section>
        `;
      }

      function FormField(field) {
        const errorId = `${field.id}-error`;
        const helpId = field.helperText ? `${field.id}-help` : "";
        const describedBy = [helpId, errorId].filter(Boolean).join(" ");
        const errorMessage = state.errors[field.name];
        const value = state.values[field.name];

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.name}"
              type="${field.type}"
              value="${escapeHtml(value)}"
              placeholder="${field.placeholder}"
              ${field.required ? "required aria-required=\"true\"" : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${errorMessage ? 'aria-invalid="true"' : ""}
              autocomplete="${field.name === "fullName" ? "name" : field.name === "email" ? "email" : "tel"}"
            />
            ${
              field.helperText
                ? `<p class="field-help" id="${helpId}">${field.helperText}</p>`
                : ""
            }
            <p class="field-error" id="${errorId}" aria-live="polite">${escapeHtml(errorMessage)}</p>
          </div>
        `;
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName") {
          if (!trimmedValue) {
            return "Enter your full name.";
          }

          if (trimmedValue.length < 2 || !trimmedValue.includes(" ")) {
            return "Enter your first and last name.";
          }
        }

        if (name === "email") {
          if (!trimmedValue) {
            return "Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
        }

        if (name === "phone") {
          if (!trimmedValue) {
            return "";
          }

          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Use digits, spaces, dashes, or parentheses for the phone number.";
          }
        }

        return "";
      }

      function validateAll() {
        const nextErrors = {};

        for (const field of fields) {
          nextErrors[field.name] = validateField(field.name, state.values[field.name]);
        }

        state.errors = nextErrors;
        return !Object.values(nextErrors).some(Boolean);
      }

      function updateField(name, value) {
        state.values[name] = value;
        state.errors[name] = validateField(name, value);
        state.status = "";
        state.statusType = "success";
        syncField(name);
        syncStatus();
      }

      function syncField(name) {
        const field = fields.find((entry) => entry.name === name);
        if (!field) {
          return;
        }

        const input = document.getElementById(field.id);
        const errorElement = document.getElementById(`${field.id}-error`);
        const errorMessage = state.errors[name];

        if (input) {
          if (input.value !== state.values[name]) {
            input.value = state.values[name];
          }

          if (errorMessage) {
            input.setAttribute("aria-invalid", "true");
          } else {
            input.removeAttribute("aria-invalid");
          }
        }

        if (errorElement) {
          errorElement.textContent = errorMessage;
        }
      }

      function syncAllFields() {
        fields.forEach((field) => {
          syncField(field.name);
        });
      }

      function syncStatus() {
        const statusElement = document.getElementById("form-status");
        if (!statusElement) {
          return;
        }

        statusElement.textContent = state.status;
        statusElement.className =
          "status-message" + (state.statusType === "error" ? " error" : "");
      }

      function focusFirstInvalidField() {
        const firstInvalidField = fields.find((field) => state.errors[field.name]);
        if (!firstInvalidField) {
          return;
        }

        const element = document.getElementById(firstInvalidField.id);
        if (element) {
          element.focus();
        }
      }

      function onSubmit(event) {
        event.preventDefault();

        if (!validateAll()) {
          state.status = "Please correct the highlighted fields and try again.";
          state.statusType = "error";
          syncAllFields();
          syncStatus();
          focusFirstInvalidField();
          return;
        }

        state.status = "Your support request is ready to send.";
        state.statusType = "success";
        syncAllFields();
        syncStatus();
      }

      function attachEvents() {
        const form = document.getElementById("contact-form");
        form.addEventListener("submit", onSubmit);

        fields.forEach((field) => {
          const input = document.getElementById(field.id);
          input.addEventListener("input", (event) => {
            updateField(field.name, event.target.value);
          });
          input.addEventListener("blur", (event) => {
            state.errors[field.name] = validateField(field.name, event.target.value);
            syncField(field.name);
          });
        });
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        attachEvents();
      }

      render();
    </script>
  </body>
</html>
